from gen import *
PW="PsychonautWiki, \"{}\" (psychonautwiki.org)"
FDA="US FDA prescribing information / DailyMed label for {}"
DEA="DEA Drug Fact Sheet and Controlled Substances schedules (dea.gov)"
NIDA="National Institute on Drug Abuse (nida.nih.gov), opioid resources"
GEN=["Goodman & Gilman's The Pharmacological Basis of Therapeutics (opioid chapter)",NIDA,DEA,"Erowid substance vaults and experience reports (erowid.org)"]

drug("morphine",name="Morphine",cls="Natural opiate (alkaloid of the opium poppy); full mu-opioid agonist. The reference drug every other opioid is compared to.",
brands="MS Contin, Kadian, Avinza (discontinued), Roxanol, Duramorph, Infumorph, Oramorph (UK), Sevredol (UK), Embeda (with naltrexone, discontinued), Arymo ER (discontinued).",
history="German pharmacist Friedrich Sertürner isolated morphine from opium around 1804 to 1817, the first alkaloid ever extracted from a plant. He named it after Morpheus, the Greek god of dreams. The invention of the hypodermic syringe in the 1850s made injected morphine common, and it was used heavily for wounded soldiers in the American Civil War and the Franco-Prussian War; dependence afterward was so common it was called \"the soldier's disease\". Morphine was sold freely in patent medicines until the Harrison Narcotics Act of 1914 in the US.",
medical="Still the gold standard for severe pain: after surgery, in cancer, in heart attacks, and in end-of-life care, where it also eases breathlessness. Given by mouth, by injection, by pump, into the spine, and as suppositories.",
recreational="Morphine was one of the first widely misused drugs of the industrial age, especially among doctors, nurses, and wealthy patients in the 1800s. Today it is less popular recreationally than oxycodone or heroin because swallowed morphine is absorbed poorly, but diverted tablets and injection remain a factor.",
legal="US Schedule II. UK Class A (low-strength preparations lower). Controlled internationally under the 1961 Single Convention.",
flavor=["Morphine's euphoria is often called the most \"classic\" or \"body-heavy\" of the opioids. People describe it as warm, sleepy, and dreamy, more sedating and less energetic than oxycodone. It produces strong histamine release, so itching and flushing are especially common; many people describe scratching their nose or face constantly.",
"Compared with heroin (which turns into morphine in the body), morphine taken the same way is described as slower to arrive and less sharp, with a smaller rush and more nausea. Compared with hydromorphone or fentanyl it is mellower and longer. Many people report a pleasant, hazy, dream-laden nod rather than a clear-headed buzz."],
itch="strong", nod="heavy",
extra_peak="Morphine is known for vivid, dream-like images at the edge of sleep, a quality behind its name.",
routes={"oral":"Tablets, capsules, oral solution; immediate- and extended-release.","rectal":"Suppositories, mainly in palliative care.","injected":"IV, IM, SC, and spinal (epidural/intrathecal) in hospitals; also misused by injection.","intranasal":"Not a common medical route; occasionally misused; absorbed poorly compared with other routes."},
skip="Not available as transdermal patch, sublingual product, or smoked form in medicine. Smoking opium (which contains morphine) is covered under Opium.",
od="Morphine and its metabolites build up in people with kidney disease and can cause delayed, prolonged overdose. Extended-release morphine taken in a damaged form releases a full day's supply at once.",
sources=[FDA.format("MS Contin and morphine sulfate injection"),PW.format("Morphine"),"Brook K, et al. \"The history of morphine\" (review literature)"]+GEN)

drug("codeine",name="Codeine",cls="Natural opiate (opium alkaloid); weak mu-opioid agonist. A prodrug: the liver enzyme CYP2D6 turns part of it into morphine.",
brands="Tylenol with Codeine (Tylenol #3, #4), Fioricet/Fiorinal with Codeine, Tuzistra XR, cough syrups such as Robitussin AC, Phenergan with Codeine (promethazine-codeine), Cheratussin AC; Co-codamol, Solpadeine, Nurofen Plus (UK).",
history="French chemist Pierre-Jean Robiquet isolated codeine from opium in 1832. Its name comes from the Greek word for poppy head. For most of the 20th century it was the standard cough suppressant and a common mild painkiller, sold over the counter in many countries.",
medical="Mild to moderate pain (usually combined with acetaminophen), cough, and diarrhea. Since 2017 the FDA has banned it for children under 12 because some people, called ultra-rapid metabolizers, turn it into morphine so fast that children died.",
recreational="Codeine cough syrup mixed with soda, called \"lean\", \"purple drank\", or \"sizzurp\", came out of the Houston hip-hop scene in the 1990s (DJ Screw's slowed-down \"chopped and screwed\" music) and spread nationwide. Several artists died from it or were hospitalized. Over-the-counter codeine misuse was also a large problem in the UK, Australia, and Nigeria, leading to tighter rules.",
legal="US: Schedule II alone; Schedule III in combination tablets; Schedule V in low-strength cough syrups. UK Class B. Available behind the pharmacy counter in some countries.",
flavor=["Codeine is the mildest of the commonly used opioids. People describe a soft, gentle, sleepy calm, with a pleasant body heaviness and a slight floaty feeling, rather than the strong euphoria of oxycodone or heroin. Itchiness is very common and often the most noticeable physical effect.",
"Because the effect depends on the CYP2D6 enzyme, people vary enormously: some feel almost nothing, others feel strong effects or become dangerously sedated. Promethazine in cough syrup adds heavy sedation and a sluggish, slowed-down, \"syrupy\" quality that people associate with lean."],
itch="strong", nod="mild to moderate",
extra_peak="The peak is usually gentle and drowsy rather than intensely euphoric; the itch can feel stronger than the high.",
routes={"oral":"Tablets and syrups; nearly all codeine use is oral.","injected":"Codeine injection existed historically and in some countries (IM/SC); rare today.","rectal":"Codeine suppositories exist in some countries."},
skip="No intranasal, transdermal, sublingual, or smoked medical forms; these are not typical routes.",
od="Ultra-rapid metabolizers can overdose on ordinary amounts. Combination tablets carry a serious risk of liver failure from acetaminophen. Promethazine-codeine syrup combines two sedatives, increasing breathing suppression, particularly with alcohol or benzos.",
sources=[FDA.format("codeine sulfate and FDA 2017 safety communication on codeine in children"),PW.format("Codeine"),"Agnich LE, et al. on lean/purple drank (Am J Drug Alcohol Abuse, 2013)"]+GEN)

drug("hydrocodone",name="Hydrocodone",cls="Semi-synthetic opioid made from codeine (or thebaine); full mu-opioid agonist.",
brands="Vicodin, Lortab, Norco, Lorcet, Zohydro ER, Hysingla ER, Vicoprofen (with ibuprofen), Hycodan and Tussionex (cough).",
history="Synthesized in Germany by Carl Mannich and Helene Löwenheim in 1920 and approved in the US in 1943. Through the 2000s, hydrocodone with acetaminophen (Vicodin and Norco) was the single most prescribed medication in the United States.",
medical="Moderate to severe pain, and cough in some products. Extended-release forms are used for long-term pain.",
recreational="Vicodin became a pop-culture name in the 1990s and 2000s (for example in TV's House, M.D.) and was central to the early prescription opioid epidemic. In 2014 the DEA moved combination products to Schedule II, sharply reducing prescriptions.",
legal="US Schedule II (all forms since 2014). Not marketed in most of Europe.",
flavor=["Hydrocodone is described as a friendly, mellow, talkative euphoria, a little lighter and more relaxed than oxycodone, with a pleasant warm body glow. Many people describe it as \"feel-good\" and sociable at first, then sleepy. It is less sharp and less 'clean-headed' than oxycodone.",
"Itching is common. Many combination tablets contain acetaminophen, which does not add to the high but makes misuse especially dangerous for the liver."],
itch="moderate", nod="moderate",
extra_peak="People often describe a chatty, contented warmth and a sense that everything is fine.",
routes={"oral":"Almost all hydrocodone is swallowed: tablets, capsules, extended-release, liquids.","intranasal":"Misused by snorting; acetaminophen fillers make it painful and harmful to nasal tissue."},
skip="No injected, rectal, transdermal, sublingual, or smoked medical forms; injection of tablets is dangerous because of fillers.",
od="Acetaminophen combination products can cause fatal liver failure. Extended-release forms (Zohydro, Hysingla) hold a large reserve that is released all at once if damaged.",
sources=[FDA.format("Norco, Zohydro ER, and Hysingla ER"),"DEA final rule rescheduling hydrocodone combination products (2014)",PW.format("Hydrocodone")]+GEN)

drug("oxycodone",name="Oxycodone",cls="Semi-synthetic opioid made from thebaine (an opium alkaloid); full mu-opioid agonist.",
brands="OxyContin, Roxicodone, Oxy IR, Xtampza ER, RoxyBond, Percocet (with acetaminophen), Percodan (with aspirin), Endocet, Roxicet, Tylox (discontinued), Oxaydo; Oxynorm (Europe), Targin/Targiniq (with naloxone).",
history="Developed in Germany in 1916 by Freund and Speyer at the University of Frankfurt, hoping for a safer alternative to heroin and morphine. Germany marketed it as Eukodal; addiction to it among the elite was called \"Eukodalism.\" Percodan reached the US in 1950 and Percocet in 1976. Purdue Pharma launched OxyContin in 1996 with aggressive marketing that understated addiction risk. Purdue pleaded guilty to federal charges in 2007 and 2020, and OxyContin is widely seen as the spark of the US opioid epidemic.",
medical="Moderate to severe pain, in immediate-release forms for short-term pain and extended-release forms for long-term pain.",
recreational="OxyContin, nicknamed \"hillbilly heroin\", spread quickly in Appalachia and rural America in the late 1990s. In 2010 Purdue reformulated it to resist tampering, which pushed many people toward heroin and later fentanyl. Today, most \"oxycodone\" pills sold on the street (\"M30s\", \"blues\") are counterfeits containing fentanyl.",
legal="US Schedule II. UK Class A. Controlled internationally.",
flavor=["Oxycodone is often described as the most euphoric of the pills: clear-headed, energetic at first, and intensely \"feel-good\". Compared with morphine, it has less itch and nausea and a brighter, more stimulating rush of well-being. Many people say it makes them chatty, confident, motivated, and affectionate before drowsiness sets in.",
"That combination of pleasure, functional energy, and relatively few side effects is a big part of why it is so habit-forming. People in recovery often describe oxycodone as the drug that made them feel \"normal\" or \"the best version of themselves\" at first, then needed just to avoid withdrawal."],
itch="mild to moderate", nod="moderate, later in the experience",
extra_peak="Many describe a clear, buoyant euphoria and motivation in the first part of the peak, sliding later into drowsy contentment.",
routes={"oral":"Immediate-release tablets, capsules, liquid; extended-release (OxyContin, Xtampza).","intranasal":"Misused by snorting, especially immediate-release pills.","injected":"Oxycodone injection is used medically in some countries (UK, Australia) but not the US; pills are also misused by injection, which is especially harmful.","rectal":"Oxycodone suppositories (Proladone) are used in Australia.","inhaled-smoked":"Misused by smoking pills on foil; counterfeit pills smoked this way often contain fentanyl."},
skip="No transdermal or sublingual products.",
od="Extended-release tablets contain a large reserve; damaging them releases it all at once, and this caused many of the early OxyContin deaths. Counterfeit \"blues\" and \"M30s\" commonly contain fentanyl and cause sudden overdose.",
sources=[FDA.format("OxyContin and Roxicodone"),"US Department of Justice, Purdue Pharma plea agreements (2007, 2020)","Van Zee A. \"The promotion and marketing of OxyContin\" (Am J Public Health, 2009)",PW.format("Oxycodone")]+GEN,
times={"oral":["15-30 min","30-45 min","1-1.5 h","1.5-3 h","3-5 h","5-12 h","next day"]})

drug("oxymorphone",name="Oxymorphone",cls="Semi-synthetic opioid; a strong full mu-opioid agonist, and also a metabolite of oxycodone.",
brands="Opana, Opana ER (removed from the US market in 2017), Numorphan (older injection and suppository).",
history="Developed in Germany in 1914 and patented in the US in 1955; Endo introduced Numorphan in 1959. Opana ER came in 2006. In 2017 the FDA asked Endo to withdraw reformulated Opana ER, the first time it removed an opioid over misuse, after injection of the reformulated tablets caused an HIV and hepatitis C outbreak in Scott County, Indiana, and a blood disorder called thrombotic microangiopathy.",
medical="Moderate to severe pain. Immediate-release generic tablets remain available in the US.",
recreational="Numorphan was popular among people who injected drugs in the 1960s and 1970s (\"blues\"). Opana ER was heavily misused in the 2010s.",
legal="US Schedule II.",
flavor=["Oxymorphone is described as strong, fast, and very heavy: more intensely euphoric and more sedating than oxycodone, with a powerful, sleepy body high. People often compare it to heroin more than to other pills.",
"It is absorbed poorly when swallowed, so experiences by mouth vary a lot. Many describe a deep, warm, sinking feeling and long nodding."],
itch="moderate", nod="heavy",
extra_peak="Described as one of the most intense pill highs, close to heroin.",
routes={"oral":"Immediate- and extended-release tablets; absorption is poor and food increases it.","injected":"Medical injection (Numorphan, historical/hospital); misuse of tablets by injection caused the Indiana outbreak.","rectal":"Numorphan suppositories (discontinued).","intranasal":"Misused by snorting; absorption through the nose is much higher than swallowing, raising overdose risk."},
skip="No transdermal, sublingual, or smoked forms.",
od="Taking it with food or alcohol can sharply raise blood levels. The removed Opana ER caused a deadly blood disorder and an HIV outbreak when injected.",
sources=[FDA.format("Opana and FDA 2017 request to remove Opana ER"),"CDC, HIV outbreak in Scott County, Indiana (MMWR 2015)",PW.format("Oxymorphone")]+GEN)

drug("hydromorphone",name="Hydromorphone",cls="Semi-synthetic opioid made from morphine; strong full mu-opioid agonist.",
brands="Dilaudid, Exalgo (extended-release, discontinued), Palladone (discontinued 2005 after dangerous interactions with alcohol), Hydromorph Contin (Canada).",
history="First made in Germany in 1924 by Knoll and sold as Dilaudid from 1926. Exalgo was approved in 2010. Palladone was withdrawn in 2005 because alcohol could make its capsule release all its drug at once.",
medical="Severe pain, especially in hospitals; given by mouth, injection, pump, and suppository. In British Columbia, Canada, hydromorphone tablets are prescribed in \"safer supply\" programs as an alternative to the fentanyl-contaminated street supply.",
recreational="Known on the street as \"dillies\" or \"D\". Popular among people who inject drugs because it dissolves easily and its effect is close to heroin.",
legal="US Schedule II. UK Class A.",
flavor=["Hydromorphone is described as clean, fast, and powerful, with less itch and nausea than morphine. By injection it is famous for an intense rush, often compared to heroin's. By mouth it is shorter-acting and sleepier than oxycodone.",
"People often describe it as a short, sharp, strong high, which leads to frequent redosing, a pattern that drives dependence."],
itch="mild", nod="moderate to heavy",
extra_peak="Strong, warm and clean, but shorter than morphine.",
routes={"oral":"Tablets, liquid, extended-release.","injected":"IV, IM, SC in hospitals; widely misused by injection.","rectal":"Dilaudid suppositories.","intranasal":"Misused by snorting; strong and fast."},
skip="No transdermal or sublingual forms; smoking is uncommon.",
od="Very potent compared with morphine, so medication errors confusing the two have killed hospital patients. Extended-release forms with alcohol can release all drug at once.",
sources=[FDA.format("Dilaudid and Exalgo"),"Institute for Safe Medication Practices, hydromorphone error alerts",PW.format("Hydromorphone")]+GEN,
times={"injected":["IV seconds; IM/SC 5-15 min","IV under 1 min","IV 5-15 min; IM/SC 30-60 min","30 min-1.5 h","1.5-3 h","3-8 h","next day"]})

drug("methadone",name="Methadone",cls="Synthetic opioid; full mu-opioid agonist with a very long, variable half-life, and an NMDA antagonist.",
brands="Dolophine, Methadose, Diskets, Physeptone (UK), Metadol (Canada).",
history="Developed in Germany in 1937 to 1939 by Max Bockmühl and Gustav Ehrhart at IG Farben, partly because Germany lacked opium supplies. After the war, the US took the patents. In the 1960s, Vincent Dole, Marie Nyswander, and Mary Jeanne Kreek in New York showed that daily methadone helped people addicted to heroin stabilize their lives, founding methadone maintenance treatment.",
medical="Opioid use disorder treatment, and long-term pain. Its long action means one daily dose prevents withdrawal for a full day.",
treatment="Methadone is one of three FDA-approved medications for opioid use disorder. In the US it can only be dispensed for addiction at certified Opioid Treatment Programs (\"methadone clinics\"), usually daily at first, with take-home doses earned over time; COVID-era rules allowing more take-homes were made permanent in 2024. Research consistently shows methadone treatment cuts the risk of death roughly in half, reduces HIV and hepatitis C spread, and reduces crime. At a stable treatment dose, people do not feel high; they feel normal, without withdrawal or craving, and can work, drive, and parent. Leaving treatment, especially suddenly, is a high-risk time for overdose because tolerance falls.",
recreational="Diverted methadone, particularly pain prescriptions in the 2000s, was linked to a disproportionate share of overdose deaths because people did not expect its slow, long build-up.",
legal="US Schedule II. UK Class A.",
flavor=["Methadone is generally described as the least euphoric of the full agonists: a heavy, warm, calm body feeling, sedation, and relief from withdrawal, rather than a rush. People without tolerance describe it as slow, dull, sleepy, and long; people on treatment describe feeling \"normal.\"",
"Its effects build up over days of repeated use because it stays in the body so long. Sweating, constipation, and drowsiness are common. People who have quit both heroin and methadone often describe methadone withdrawal as milder but much longer, lasting weeks."],
itch="mild", nod="moderate",
extra_peak="The peak is vague and drawn-out rather than sharp, which fools people into thinking it is weaker than it is.",
after="Effects last much longer than other opioids, often 24 hours or more, and drug keeps building in the body with repeated use. Sweating, constipation, and drowsiness persist.",
nextday="The next day, drug is often still active. Methadone's long half-life (roughly 8 to 59 hours) means a second day of use adds on top of the first.",
routes={"oral":"Tablets, dispersible tablets, and liquid concentrate; the standard route for addiction treatment.","injected":"Medical injection exists for patients who cannot swallow; misuse by injection is harmful because of fillers.","rectal":"Used in palliative care when patients cannot swallow."},
skip="No transdermal, sublingual, intranasal, or smoked forms.",
od="Methadone overdose is often delayed and long-lasting. Peak breathing suppression can come hours after the peak 'feeling', and deaths often occur during sleep, the night of use or in the first days of starting or increasing. Naloxone wears off far sooner than methadone, so repeated doses and hospital monitoring are needed. Methadone can also cause a dangerous heart rhythm (QT prolongation). Combining with benzodiazepines or alcohol is especially dangerous.",
sources=[FDA.format("Dolophine and Methadose"),"Dole VP, Nyswander M. JAMA 1965, methadone maintenance","SAMHSA TIP 63: Medications for Opioid Use Disorder","Sordo L, et al. BMJ 2017, mortality in and out of opioid agonist treatment",PW.format("Methadone")]+GEN,
times={"oral":["30-60 min","1-2 h","2-4 h","4-12 h","12-36 h","24-72 h","still active"],"injected":["IV under 1 min; IM 10-20 min","IV a few minutes","IV 10-30 min","1-8 h","8-36 h","24-72 h","still active"],"rectal":["30-60 min","1-2 h","2-4 h","4-12 h","12-36 h","24-72 h","still active"]})

drug("buprenorphine",name="Buprenorphine (Subutex, Suboxone)",cls="Semi-synthetic opioid made from thebaine; a partial mu-opioid agonist with very strong receptor binding and a 'ceiling effect' on breathing suppression.",
brands="Subutex (buprenorphine alone, brand discontinued in US, generics remain), Suboxone (with naloxone), Zubsolv, Bunavail (discontinued), Sublocade and Brixadi (monthly/weekly injections), Probuphine (implant, discontinued), Butrans (patch, pain), Belbuca (buccal film, pain), Buprenex (injection, pain).",
history="Developed by Reckitt & Colman (now Indivior) in Britain, first made in 1966 by John Lewis's team, and launched as an injectable painkiller (Temgesic) in 1978. Research in the 1970s and 1980s showed it could treat opioid addiction. The US Drug Addiction Treatment Act of 2000 let doctors prescribe it for addiction from an office, and Subutex and Suboxone were approved in 2002. In 2023 the special 'X-waiver' was removed, so any clinician with a standard DEA registration can prescribe it.",
medical="Opioid use disorder treatment, and chronic pain (patches, buccal films, injections).",
treatment="Buprenorphine is one of three FDA-approved medications for opioid use disorder, and the one most available outside clinics: it can be prescribed in a doctor's office or by telehealth and picked up at a pharmacy. Its strong grip on opioid receptors blocks other opioids from working fully and stops craving and withdrawal. Starting it too early, while another opioid is still active, can cause 'precipitated withdrawal', a sudden severe sickness, which is why patients are told to wait for mild withdrawal first or use newer low-dose starting methods under a clinician. Suboxone adds naloxone to discourage injection. Like methadone, it roughly halves the risk of death while people stay in treatment.",
recreational="Diverted buprenorphine is mostly used to self-treat withdrawal rather than to get high. In some countries, including France and Finland, Subutex injection became a major problem in the 2000s.",
legal="US Schedule III. UK Class C.",
flavor=["For people without opioid tolerance, buprenorphine can be surprisingly strong: a long, warm, mellow, slightly spacey euphoria with heavy nausea and sleepiness, often lasting a day or more. For people with tolerance, it produces little euphoria; instead people describe relief, clear-headedness, and feeling \"normal.\" Many in recovery value exactly that flatness.",
"Because it is a partial agonist with a ceiling, the high does not keep climbing the way full agonists do. Users often describe it as \"cleaner\" and more energetic than methadone. Nausea and headaches are common at first."],
itch="mild", nod="mild to moderate",
extra_peak="In non-tolerant people the peak is gentle but long and often nauseating; in tolerant people there may be no noticeable peak at all.",
after="Effects last 24 to 72 hours; constipation, headache, and sleepiness linger.",
nextday="Often still active the next day or longer, due to its very long action.",
routes={"sublingual-buccal":"Subutex and Suboxone tablets and films under the tongue; Belbuca buccal film; Zubsolv. The main route.","injected":"Buprenex injection for pain; Sublocade and Brixadi monthly or weekly injections under the skin for addiction; also misused by IV injection.","transdermal":"Butrans patch for chronic pain.","intranasal":"Misused by snorting; absorption is faster than sublingual."},
skip="Swallowed buprenorphine is poorly absorbed, so oral is not a medical route. No rectal or smoked forms.",
od="Its ceiling effect makes overdose from buprenorphine alone much less likely in adults, but combining it with benzodiazepines, alcohol, or other sedatives has caused many deaths. Children who swallow films or tablets can die. Naloxone still helps, though higher amounts may be needed because buprenorphine binds so tightly. Precipitated withdrawal is not an overdose, but it is severe.",
sources=[FDA.format("Suboxone, Subutex, Sublocade, Butrans"),"SAMHSA TIP 63","Campbell ND, Lovell AM. History of buprenorphine (Ann NY Acad Sci, 2012)","Dahan A, et al. Buprenorphine ceiling effect on respiration (Br J Anaesth, 2006)",PW.format("Buprenorphine")]+GEN,
times={"sublingual-buccal":["30-60 min","1-2 h","1-4 h","4-12 h","12-48 h","24-72 h","still active"],"transdermal":["12-24 h","24-48 h","~3 days","while patch on","24+ h after removal","2-3 days","after removal"],"intranasal":["10-20 min","20-40 min","1-2 h","2-12 h","12-36 h","24-72 h","still active"],"injected":["IV 5-15 min","IV 15-30 min","IV 30-60 min","1-12 h","12-36 h","24-72 h (much longer for monthly injections)","still active"]})

drug("fentanyl",name="Fentanyl (pharmaceutical)",cls="Synthetic opioid of the 4-anilidopiperidine family; very potent full mu-opioid agonist, roughly 50 to 100 times stronger than morphine by weight.",
brands="Sublimaze (injection), Duragesic (patch), Actiq (lozenge on a stick), Fentora (buccal tablet), Abstral (sublingual tablet), Subsys (sublingual spray), Lazanda and Instanyl (nasal sprays), Onsolis (buccal film), Ionsys (iontophoretic system, discontinued).",
history="Paul Janssen synthesized fentanyl in Belgium in 1960. It entered anesthesia as Sublimaze in the 1960s and the Duragesic patch came in 1990. Fast-acting 'breakthrough' products for cancer pain followed in the 2000s. Insys Therapeutics executives were convicted in 2019 for bribing doctors to prescribe the Subsys spray.",
medical="Anesthesia, intensive care, severe pain in hospitals, chronic cancer pain (patches), and breakthrough cancer pain in opioid-tolerant patients.",
recreational="Pharmaceutical fentanyl patches have been diverted and misused since the 1990s. Illicit fentanyl is covered on its own page.",
legal="US Schedule II. Most analogs are Schedule I, and since 2018 fentanyl-related substances are controlled as a class.",
flavor=["Fentanyl's effect is described as fast, intense, and short: a strong wave of warmth and sedation, more 'blank' and sleepy than euphoric, with less of the dreamy, glowing warmth of heroin or morphine. Many people say it hits hard and wears off quickly, leaving them wanting more.",
"From a patch, the effect is slow and constant: steady pain relief, drowsiness, and nausea rather than euphoria."],
itch="mild", nod="heavy and sudden",
extra_peak="Sedation can come on so fast that people pass out without warning.",
after="Effects fade quickly with fast routes (often within 1 to 2 hours), but fentanyl stored in fat can extend after-effects with repeated use.",
routes={"injected":"IV in anesthesia and intensive care; IM in some settings.","transdermal":"Duragesic and generic patches.","sublingual-buccal":"Actiq, Fentora, Abstral, Subsys, Onsolis.","intranasal":"Lazanda/Instanyl sprays; in some hospitals and ambulances for pain.","inhaled-smoked":"Nebulized fentanyl is used occasionally in hospitals; smoking is a common illicit route."},
skip="Swallowed fentanyl is poorly absorbed, so oral is not a medical route. No rectal products.",
od="Fentanyl overdose can happen within seconds to minutes. It can cause 'wooden chest' (chest-wall rigidity), where the breathing muscles go stiff. More than one naloxone dose may be needed. Heat on a patch speeds release.",
sources=[FDA.format("Sublimaze, Duragesic, Actiq, Fentora"),"Stanley TH. The fentanyl story (J Pain, 2014)","US DOJ, Insys Therapeutics convictions (2019)",PW.format("Fentanyl")]+GEN,
times={"injected":["IV seconds","IV under 1 min","IV 3-5 min","5-30 min","30-60 min","1-4 h","next day"],"intranasal":["5-10 min","5-15 min","15-30 min","30-60 min","1-2 h","2-6 h","next day"],"sublingual-buccal":["5-15 min","15-30 min","20-45 min","45-90 min","1-3 h","3-8 h","next day"],"inhaled-smoked":["seconds","seconds","1-3 min","5-20 min","20-60 min","1-4 h","next day"]})

drug("fentanyl-illicit",name="Illicit fentanyl",cls="Illegally manufactured fentanyl and fentanyl analogs (such as carfentanil, acetylfentanyl, and others), sold as powder or pressed into counterfeit pills.",
brands="No brands. Street names include \"fent\", \"fetty\", \"blues\", \"M30s\", \"dance fever\", \"China white\", \"tango and cash\".",
history="Isolated outbreaks of street fentanyl appeared in the US from the late 1970s ('China white'). From around 2013, illegally made fentanyl, often from chemicals produced overseas, replaced much of the heroin supply in North America. By 2016 it was the leading cause of overdose death, and synthetic opioids caused around 70,000 US deaths a year at the peak around 2022 to 2023. Newer adulterants include xylazine ('tranq'), an animal sedative that causes severe wounds, and nitazenes, a separate family of synthetic opioids.",
medical="None. Illicit fentanyl is not made to any medical standard.",
recreational="Most people who die from fentanyl did not know they were taking it: it is mixed into heroin, counterfeit oxycodone and Xanax pills, cocaine, and methamphetamine. Many people with opioid use disorder now use it knowingly because it has displaced heroin.",
legal="US Schedule II for fentanyl; analogs Schedule I as a class.",
flavor=["People describe illicit fentanyl as a fast, heavy, short high, with less of heroin's warm, dreamy euphoria and more blank sedation, followed by quick, harsh withdrawal a few hours later. Many describe it as 'chasing', needing to use again and again through the day.",
"Because pressed pills and powders are mixed unevenly ('chocolate chip cookie effect'), one part may contain little and another a deadly amount. Xylazine adds very long blackouts and skin wounds."],
itch="mild", nod="heavy and sudden",
extra_peak="People often lose consciousness quickly; many survivors say they never felt it coming.",
after="Short duration often means withdrawal starts within hours, with restlessness and sweats.",
routes={"inhaled-smoked":"Smoking on foil is now the most common way illicit fentanyl is used in many areas.","injected":"Injected, often mixed with other drugs.","intranasal":"Snorted, often unknowingly in powders sold as other drugs.","oral":"Swallowed as counterfeit pills."},
skip="No rectal, transdermal, or sublingual illicit use is common enough to cover.",
od="Overdose often comes within seconds to minutes, sometimes before the person can put the drug down. Chest-wall rigidity ('wooden chest') can make breathing impossible. Multiple naloxone doses may be needed. Fentanyl test strips can detect it in drugs before use, and are legal in most US states. Never use alone; services like the Never Use Alone hotline (1-877-696-1996) send help if a caller stops responding.",
sources=["CDC National Center for Health Statistics, drug overdose deaths data","DEA National Drug Threat Assessment (2024, 2025)",NIDA+", fentanyl drug facts","Ciccarone D. The rise of illicit fentanyls (Curr Opin Psychiatry, 2021)","Never Use Alone (neverusealone.com)"]+GEN[2:],
times={"inhaled-smoked":["seconds","seconds","1-3 min","5-20 min","20-60 min","1-4 h","withdrawal may begin"],"injected":["seconds","under 1 min","2-5 min","5-30 min","30-90 min","1-4 h","withdrawal may begin"],"intranasal":["2-10 min","5-15 min","10-30 min","30-60 min","1-2 h","2-6 h","withdrawal may begin"],"oral":["10-30 min","20-40 min","30-60 min","1-2 h","2-4 h","4-8 h","withdrawal may begin"]})

drug("heroin",name="Heroin (diacetylmorphine)",cls="Semi-synthetic opioid made from morphine; a prodrug that becomes 6-monoacetylmorphine and morphine in the body, and enters the brain faster than morphine.",
brands="Heroin (Bayer, 1898 to about 1913); Diamorphine (UK medical use).",
history="C.R. Alder Wright first made diacetylmorphine in London in 1874. In 1897 Felix Hoffmann at Bayer (who also made aspirin) re-made it, and Bayer sold it from 1898 as 'Heroin' (from German 'heroisch', heroic), a cough medicine and supposedly non-addictive morphine substitute, even for children. Within a few years its addictiveness was obvious; Bayer stopped making it around 1913, the US Harrison Act of 1914 restricted it, and it was banned in the US in 1924. Heroin waves followed in the 1950s to 1970s (including among Vietnam veterans) and again from the 2000s, when people with prescription opioid addiction switched to cheaper heroin. Since about 2013, the US heroin supply has been largely replaced or contaminated by fentanyl.",
medical="As diamorphine, used in the UK and some other countries for severe pain, heart attacks, and palliative care. Switzerland, the Netherlands, Germany, Denmark, and Canada run heroin-assisted treatment for people for whom other treatments have not worked.",
recreational="One of the most well-known drugs of misuse in the world, linked with jazz and rock subcultures and later with the overdose crisis.",
legal="US Schedule I (no accepted medical use). UK Class A, but prescribable as diamorphine.",
flavor=["Heroin is often described as the deepest, warmest, most complete opioid euphoria: a body-wide warmth and safety, \"like being hugged by God\" or \"returning to the womb\", with all pain, anxiety, and loneliness gone. Compared with morphine it arrives faster and feels sharper; compared with fentanyl it is warmer, dreamier, and longer.",
"Writers like Thomas De Quincey (on opium), William Burroughs, and many people in recovery have described how this feeling becomes the center of life, and then turns into the daily need to avoid withdrawal. Today, almost all street 'heroin' in North America contains fentanyl, so the experience and risk are no longer what they were."],
itch="strong", nod="heavy",
extra_peak="The peak is often described as a deep, golden, dreamy calm, with heavy nodding.",
routes={"injected":"IV, IM ('muscling'), and SC ('skin-popping'); medical diamorphine injection in the UK.","inhaled-smoked":"'Chasing the dragon', smoking vapor from foil.","intranasal":"Snorting, common with powder heroin; medical diamorphine nasal spray is used for children's pain in UK emergency departments.","oral":"Medical diamorphine tablets exist in the UK; swallowed heroin largely turns into morphine and feels like oral morphine."},
skip="No transdermal or common rectal use; rectal use exists but is rare and not covered.",
od="Since street heroin now usually contains fentanyl, overdose risk is unpredictable. Overdoses cluster after time away from use (jail, rehab, hospital), when tolerance is lower.",
sources=["Sneader W. The discovery of heroin (Lancet, 1998)","Bayer heroin history, Courtwright DT, Dark Paradise (Harvard University Press)","UK BNF, diamorphine","Strang J, et al. Heroin-assisted treatment (Br J Psychiatry, 2015)",PW.format("Heroin")]+GEN,
times={"oral":["20-45 min","30-60 min","1-2 h","2-4 h","4-6 h","6-24 h","next day"]})

drug("tramadol",name="Tramadol",cls="Synthetic, weak mu-opioid agonist (mostly through its metabolite O-desmethyltramadol, made by CYP2D6) that also blocks reuptake of serotonin and norepinephrine, like an antidepressant.",
brands="Ultram, Ultram ER, Ultracet (with acetaminophen), ConZip, Ryzolt (discontinued), Tramal, Zydol (UK), Seglentis (with celecoxib).",
history="Developed by the German company Grünenthal in 1962 and marketed from 1977; approved in the US in 1995. It was long marketed as low-risk and was not federally controlled in the US until 2014.",
medical="Moderate pain.",
recreational="Widely misused in West Africa, the Middle East, and North Africa, where cheap high-strength tablets ('tramol', 'Tamol') are trafficked, and among people seeking a milder opioid in the US and Europe.",
legal="US Schedule IV (since 2014). UK Class C.",
flavor=["Tramadol is described as a mild, stimulating, 'happy' opioid: a mix of light opioid warmth and an antidepressant-like lift in mood and energy, sometimes with restlessness. Many say it feels more like a pleasant buzz than a nod.",
"Side effects are distinctive: nausea, sweating, dizziness, and feeling 'wired' or anxious. Withdrawal can include unusual symptoms like tingling, panic, and confusion, because of its serotonin and norepinephrine effects."],
itch="mild", nod="mild",
extra_peak="Peak often feels energetic and talkative more than sedated.",
routes={"oral":"Tablets, capsules, extended-release; nearly all use is oral.","injected":"Injectable tramadol is used medically outside the US.","rectal":"Suppositories exist in some countries."},
skip="No intranasal, transdermal, sublingual, or smoked forms.",
od="Tramadol can cause seizures, even at ordinary amounts and more in overdose or with other drugs that lower the seizure threshold. Combined with antidepressants and other serotonergic drugs it can cause serotonin syndrome (agitation, high fever, muscle twitching, confusion). Naloxone reverses breathing suppression but not seizures.",
sources=[FDA.format("Ultram"),"WHO Expert Committee on Drug Dependence, tramadol review (2014, 2018)","UNODC, tramadol trafficking in West Africa",PW.format("Tramadol")]+GEN)

drug("tapentadol",name="Tapentadol",cls="Synthetic mu-opioid agonist that also blocks norepinephrine reuptake.",
brands="Nucynta, Nucynta ER, Palexia (Europe).",
history="Developed by Grünenthal and approved in the US in 2008.",
medical="Moderate to severe pain, including diabetic nerve pain (ER).",
recreational="Less popular than oxycodone but increasingly misused, especially in India and parts of Africa.",
legal="US Schedule II.",
flavor=["Tapentadol is described as a clean, mild-to-moderate opioid warmth with alertness from its norepinephrine effect, and less nausea and constipation than oxycodone. Many say it is less euphoric than oxycodone and more 'functional'.",
"Some report dizziness, sweating, and a slightly edgy feeling. Like tramadol, it carries some seizure and serotonin risk."],
itch="mild", nod="mild to moderate",
routes={"oral":"Immediate- and extended-release tablets; the only medical route."},
skip="No other medical routes.",
od="Seizure and serotonin syndrome risk, especially with antidepressants. Extended-release forms can release all their drug at once if damaged.",
sources=[FDA.format("Nucynta"),PW.format("Tapentadol")]+GEN)
